const items=$input.all();
const groups=new Map();
for(let i=0;i<items.length;i++){
 const j=items[i].json;
 if(!j.sourceMessageId||!j.sourceAttachmentKey||!j.invoiceNumber) throw new Error('Missing saved CloudProvider source identity');
 const key=j.sourceMessageId+'|'+j.invoiceNumber;
 if(!groups.has(key)) groups.set(key,{json:{...j,savedDocuments:[]},pairedItem:{item:i}});
 const g=groups.get(key),r=g.json;
 if(r.date!==j.date || r.amount!==j.amount || (r.account&&j.account&&r.account!==j.account)) throw new Error('CloudProvider invoice metadata conflict');
 if(r.savedDocuments.some(d=>d.sourceAttachmentKey===j.sourceAttachmentKey||d.fileName===j.fileName)) throw new Error('CloudProvider duplicate saved attachment or filename conflict');
 r.account=r.account||j.account;
 r.fileName=j.registerFileName||r.fileName;
 r.savedDocuments.push({sourceAttachmentKey:j.sourceAttachmentKey,fileName:j.fileName,targetPath:j.targetPath});
 if(j.documentKind==='invoice') r.fileName=j.fileName;
}
return [...groups.values()];

return $input.all().map((item,i)=>{
 const src=$("Restore hosting invoice").itemMatching(i).json;
 const row=item.json;
 if(!src.sourceMessageId || !src.sourceAttachmentKey || String(row.invoiceNumber ?? row['Numero Fattura'] ?? '')!==src.invoiceNumber)
   throw new Error('Invoice register confirmation mismatch; email retained');
 if(row.File!==undefined && row.File!==src.fileName)throw new Error('Invoice filename confirmation mismatch; email retained');
 return {json:{status:'archived',sourceMessageId:src.sourceMessageId,sourceAttachmentKey:src.sourceAttachmentKey,
  invoiceNumber:src.invoiceNumber,fileName:src.fileName},pairedItem:{item:i}};
});

