const src=$('Parse invoice and canonical name').item;
if (!src?.json?.sourceMessageId || !src?.binary?.data) throw new Error('Parsed item or PDF missing; refusing to continue');
return {json:src.json,binary:src.binary};

try {
  const parsed = (() => {
const source = $('Normalize PDF binary').item;
if (!source?.json) throw new Error('Missing paired source PDF');
const bin = source.binary || {};
const b = bin.data || {};
const text = String(item.json.text || item.json.data || item.json.output || item.json.content || item.json.document || '').replace(/\r/g,'');
if (text.trim().length < 30) throw new Error('Empty or image-only PDF: OCR needed');
const subject = String(source.json.subject || '');
const from = String(source.json.from?.text || source.json.from || source.json.sender || '').toLowerCase();
function normDate(y,m,d){return `${y}-${String(m).padStart(2,'0')}-${String(d).padStart(2,'0')}`}
function ymd(s){return String(s||'').replace(/-/g,'')}
function money(v){ if(v==null) return null; let s=String(v).replace(/\s|€/g,''); if(s.includes(',')&&s.includes('.')) s=s.replace(/\./g,'').replace(',','.'); else s=s.replace(',','.'); const n=Number(s.replace(/[^0-9.-]/g,'')); return Number.isFinite(n)?Math.round(n*100)/100:null; }
function m1(pat){ const m=text.match(pat); return m?m[1]:null; }
function dateFromText(){
 for (const pat of [/(?:Data fattura|DATA FATTURA|Data del documento|Documento del|Invoice date|Data)\D{0,35}(\d{1,2})[/-](\d{1,2})[/-](20\d{2})/i,/(\d{1,2})[/-](\d{1,2})[/-](20\d{2})/]) { const m=text.match(pat); if(m) return normDate(m[3],m[2],m[1]); }
 for (const pat of [/(?:Invoice date|Date of invoice|Rechnungsdatum)\D{0,35}(\d{1,2})[./-](\d{1,2})[./-](20\d{2})/i, /(?:Invoice date|Date of invoice|Rechnungsdatum)\D{0,35}(20\d{2})[-/.](\d{1,2})[-/.](\d{1,2})/i]) { const m=text.match(pat); if(m) return m[1].length===4?normDate(m[1],m[2],m[3]):normDate(m[3],m[2],m[1]); }
 return '';
}
let provider='', type='', invoice='', date='', amount=null, account='', tab='', folder='';
if (from.includes('utility-provider') || /Utility Provider/i.test(text+subject)) {
 provider='UtilityProvider';
 const head=(text.slice(0,5000)+' '+subject);
 const luce=/bolletta\s+luce/i.test(head) || /fornitura:\s*energia\s+elettrica/i.test(head) || /\bkWh\b/i.test(head);
 const gas=/bolletta\s+gas/i.test(head) || /fornitura:\s*gas/i.test(head) || /\bSmc\b/i.test(head);
 if (luce && !gas) type='electricity'; else if (gas && !luce) type='gas'; else throw new Error(`UtilityProvider type ambiguous: luce=${luce} gas=${gas} file=${b.fileName||''} subject=${subject}`);
 invoice=m1(/(UT-\d{4}-\d+)/i) || (b.fileName||'').match(/(UT-\d{4}-\d+)/i)?.[1] || m1(/(?:NUMERO FATTURA ELETTRONICA VALIDA AI FINI FISCALI|Fattura n:)\s*([A-Z0-9-]+)/i) || '';
 date=dateFromText();
 amount=money(m1(/Questo mese dovrai pagare\s*\n\s*([0-9]+[,.][0-9]{2})\s*€/i) || m1(/Totale:\s*([0-9]+[,.][0-9]{2})\s*€/i) || m1(/Totale importo da pagare\s*\n\s*€?\s*([0-9]+[,.][0-9]{2})/i) || m1(/Totale \(IVA inclusa\)\s*:?\s*([0-9]+[,.][0-9]{2})/i) || m1(/TOTALE DA PAGARE\s*([0-9]+[,.][0-9]{2})/i));
 tab='Utilities'; folder=`/invoices/utilities/${type}`;
} else if (from.includes('internet-provider') || /Internet Provider/i.test(text+subject)) {
 provider='InternetProvider'; type='internet'; invoice=(text.match(/(\d{5,})\s*\/\s*([A-Z])\s*\/\s*(20\d{2})/)||[]).slice(1).join('-') || '';
 date=dateFromText(); amount=money(m1(/TOTALE\s+FATTURA\s*([0-9]+[,.][0-9]{2})/i)); tab='Internet'; folder='/invoices/internet';
} else if (from.includes('hosting-provider') || /Hosting Provider/i.test(text+subject)) {
 provider='HostingProvider'; type='cloud';
 invoice=m1(/(?:Invoice\s*(?:number|no\.?|#)|Rechnungs(?:nummer|nr\.? )|Invoice\s*No\.?|Fattura\s*n\.?)[\s:#-]*([A-Z0-9][A-Z0-9\/-]{3,})/i) || String(b.fileName||'').match(/(?:invoice|rechnung)[-_\s]*([0-9]{5,})/i)?.[1] || '';
 date=dateFromText();
 // HostingProvider overview: Service | Period | Total (excl. VAT) | Tax | Total.
 // Read the final total on the overview row, not the net amount.
 // PDF extraction may put each table cell on a separate line.
 // Restrict extraction to Overview, before payment instructions / product details.
 const overview=text.match(/\bOverview\b([\s\S]*?)(?:Please pay|Click here|Due upon receipt|\bProduct\s+count\b)/i)?.[1] || '';
 const overviewLines=overview.split('\n').map(x=>x.trim()).filter(Boolean);
 let gross=null, net=null, vat=null, service='';
 const amounts=[...overview.matchAll(/€\s*([\d.,]+[.,]\d{2})(?!\d)/g)].map(m=>money(m[1]));
 // In the HostingProvider Overview each service row ends in net, tax, gross.
 // The last three monetary values in the overview are the final totals.
 if(amounts.length>=3 && amounts.length%3===0) {
   net=amounts[amounts.length-3];
   vat=amounts[amounts.length-2];
   gross=amounts[amounts.length-1];
 }
 // Require arithmetic consistency; never silently fall back to net.
 if(gross===null || net===null || vat===null || Math.abs((net+vat)-gross)>0.02)
   throw new Error(`HostingProvider Overview totals invalid: monetary values=${JSON.stringify(amounts)}`);
 amount=gross;
 const productMatch=text.match(/\b(ST\d+\s+Storage Plan|(?:VM|ST)\d+[A-Z0-9-]*\s+[^\n€]{0,65}|Storage Plan|Cloud Server)\b/i);
 service=productMatch?.[1]?.trim() || overviewLines.find(l=>/^(?:Storage|Cloud|Server|Domain|Web Hosting|Managed|Networking)\s+\d{2}\/20\d{2}/i.test(l))?.split(/\s+\d{2}\/20\d{2}/)[0] || '';
 account=m1(/(?:Customer\s*(?:number|ID)|Kundennummer|Client\s*ID)[\s:#-]*([A-Z0-9-]+)/i)||'';
 item.json.service=service;
 item.json.netAmount=net;
 item.json.vatAmount=vat;
 tab='Hosting'; folder='/invoices/hosting';
} else if (from.includes('cloud-provider') || /Cloud Provider/i.test(text+subject)) {
 provider='CloudProvider'; type='cloud'; invoice=m1(/(CINV\d+)/i) || ''; date=dateFromText();
 // Google summary dates are localized and can precede the extracted labels.
 if(!date) {
   const months={gen:1,feb:2,mar:3,apr:4,mag:5,giu:6,lug:7,ago:8,set:9,ott:10,nov:11,dic:12};
   const dm=text.match(/(?:Data fattura\s*[:.]?\s*|\.{3,}\s*)(\d{1,2})\s+(gen(?:naio)?|feb(?:braio)?|mar(?:zo)?|apr(?:ile)?|mag(?:gio)?|giu(?:gno)?|lug(?:lio)?|ago(?:sto)?|set(?:tembre)?|ott(?:obre)?|nov(?:embre)?|dic(?:embre)?)\.?\s+(20\d{2})/i);
   if(dm) {
     const y=Number(dm[3]),m=months[dm[2].slice(0,3).toLowerCase()],d=Number(dm[1]);
     const dt=new Date(Date.UTC(y,m-1,d));
     if(dt.getUTCFullYear()===y && dt.getUTCMonth()===m-1 && dt.getUTCDate()===d) date=normDate(y,m,d);
   }
 }
 account=m1(/ID account\s*[:.]?\s*([0-9A-Z]{6}-[0-9A-Z]{6}-[0-9A-Z]{6})/i)||m1(/\b([0-9A-F]{6}-[0-9A-F]{6}-[0-9A-F]{6})\b/i)||'';
 const explicitTotal=m1(/Importo totale\s*:?\s*€?\s*(-?[0-9]+[,.][0-9]{2})/i);
 if(explicitTotal!==null) amount=money(explicitTotal);
 else {
   // Extracted summary puts the net/VAT/gross values BEFORE their labels.
   // Require a complete totals block and arithmetic, never a lone adjacent value.
   const totals=[...text.matchAll(/(-?[\d.,]+[,.]\d{2})\s*€\s*\n\s*(-?[\d.,]+[,.]\d{2})\s*€\s*\n\s*(-?[\d.,]+[,.]\d{2})\s*€\s*\n\s*(?:Riepilogo[^\n]*\n\s*)?Imponibile in EUR\s*\n\s*IVA[^\n]*\n\s*Totale in EUR/gi)];
   if(!totals.length) throw new Error('CloudProvider gross totals block missing; refusing net fallback');
   const values=totals.map(m=>m.slice(1,4).map(money));
   if(values.some(([net,vat,gross])=>[net,vat,gross].some(v=>v===null)||Math.abs(net+vat-gross)>0.011)||values.some(v=>v[2]!==values[0][2])) throw new Error('CloudProvider net/VAT/gross totals inconsistent');
   amount=values[0][2]; item.json.netAmount=values[0][0]; item.json.vatAmount=values[0][1];
 }
 tab='Cloud'; folder='/invoices/cloud';
}
if(!provider || !type || !invoice || !date || amount===null) throw new Error(`Cannot parse invoice: provider=${provider} type=${type} invoice=${invoice} date=${date} amount=${amount} file=${b.fileName||''} subject=${subject}`);
const registerFileName = `${ymd(date)} ${type} ${provider} ${invoice}.pdf`;
const isGoogleSummary=provider==='CloudProvider' && /Questo è un riepilogo della fattura elettronica/i.test(text);
const fileName=isGoogleSummary?registerFileName.replace(/\.pdf$/,' riepilogo.pdf'):registerFileName;
return {json:{provider,type,invoiceNumber:invoice,uniqueKey:`${provider}:${invoice}`, date,amount,account,service:item.json.service||'',netAmount:item.json.netAmount??null,vatAmount:item.json.vatAmount??null,tab,fileName,registerFileName,documentKind:isGoogleSummary?'summary':'invoice',targetPath:`${folder}/${fileName}`,sourceMessageId:source.json.id||source.json.messageId||'',sourceAttachmentKey:source.json.attachmentKey||'',subject}, binary:{data:{...b,fileName}}};
  })();
  if ($json.error) throw new Error(String($json.error.message || $json.error));
  parsed.json.status = 'validated';
  return parsed;
} catch (error) {
  const src = $('Normalize PDF binary').item;
  if (!src?.json?.id && !src?.json?.messageId) throw error;
  return {json:{sourceMessageId:String(src.json.id || src.json.messageId),
    sourceAttachmentKey:src.json.attachmentKey, originalFileName:src.json.originalFileName,
    fileName:src.json.originalFileName || src.binary?.data?.fileName || '',
    subject:src.json.subject || '', status:'review', reason:String(error.message || error)},
    binary:src.binary};
}

const out=[];
for (let i=0;i<items.length;i++) {
 const it=items[i];
 for (const [key,b] of Object.entries(it.binary||{})) {
  const name=String(b.fileName||b.filename||'');
  const mime=String(b.mimeType||'').toLowerCase();
  if (!(name.toLowerCase().endsWith('.pdf')||mime==='application/pdf')) continue;
  const bytes=await this.helpers.getBinaryDataBuffer(i,key);
  if(bytes.length>20*1024*1024)throw new Error('PDF exceeds 20 MiB: '+name);
  out.push({json:{...it.json,attachmentKey:key,originalFileName:name},binary:{data:{...b,fileName:name||'invoice.pdf'}},pairedItem:{item:i}});
 }
}
return out;

const src=$input.item;
const j=src.json;
const columns={UtilityProvider:'uniqueKey',InternetProvider:'invoiceNumber',CloudProvider:'Numero Fattura',HostingProvider:'Numero Fattura'};
if(!columns[j.provider] || !j.tab || !j.sourceMessageId || !j.sourceAttachmentKey || !src.binary?.data)
  throw new Error('Missing validated invoice identity or PDF');
const bytes=await this.helpers.getBinaryDataBuffer(0,'data');
return {json:{...j,lookupColumn:columns[j.provider],lookupValue:j.provider==='UtilityProvider'?j.uniqueKey:j.invoiceNumber,
  pdfBytes:bytes.length,targetFolder:j.targetPath.slice(0,j.targetPath.lastIndexOf('/'))},binary:src.binary};

const src=$('Prepare duplicate lookup').item;
const j=src.json;
const rows=$input.all().map(i=>i.json).filter(r=>Object.keys(r).length);
const normalizeDate=value=>{
 if(typeof value==='number')return new Date(Date.UTC(1899,11,30)+Math.round(value)*86400000).toISOString().slice(0,10);
 const s=String(value??'').trim();
 if(/^\d{4}-\d{2}-\d{2}/.test(s))return s.slice(0,10);
 const m=/^(\d{1,2})[./-](\d{1,2})[./-](\d{4})$/.exec(s);
 return m?`${m[3]}-${m[2].padStart(2,'0')}-${m[1].padStart(2,'0')}`:s;
};
let decision=rows.length?'registered':'upload',reason='';
if(rows.length>1) {decision='review';reason='Multiple invoice register rows match the invoice identity';}
if(rows.length===1) {
 const r=rows[0],number=String(r.invoiceNumber ?? r['Numero Fattura'] ?? '');
 const raw=r.amount ?? r.IMPORTO ?? r.Importo;
 const amount=typeof raw==='number'?raw:Number(String(raw??'').replace(/\s|€/g,'').replace(',','.'));
 const rowDate=normalizeDate(r.date ?? r['Data Fattura'] ?? r.Data ?? '');
 if(number!==j.invoiceNumber || raw===null || raw===undefined || raw==='' || !Number.isFinite(amount) || Math.abs(amount-j.amount)>0.011 || rowDate!==j.date) {
   decision='review';reason='Registered invoice metadata differs from this PDF (number, date or amount)';
 }
}
return [{json:{...j,decision,reason},binary:src.binary}];

const src=$('Assess registered invoice').item;
const j=src.json;
const matches=$input.all().map(i=>i.json).filter(f=>f.name===j.fileName && f.type!=='d');
let decision='upload',reason='';
if(matches.length>1) {decision='review';reason='Multiple SFTP entries match the canonical PDF filename';}
else if(matches.length===1) {
 if(Number(matches[0].size)===j.pdfBytes && j.pdfBytes>0) decision='duplicate';
 else {decision='review';reason='Registered SFTP PDF size differs from the email attachment';}
}
return [{json:{...j,decision,reason},binary:src.binary}];

const j=$json;
if(j.decision!=='duplicate')throw new Error('Duplicate completion requires a verified register and SFTP file');
return {json:{status:'duplicate',sourceMessageId:j.sourceMessageId,sourceAttachmentKey:j.sourceAttachmentKey,
 invoiceNumber:j.invoiceNumber,fileName:j.fileName}};

const j=$json;
if(!j.sourceMessageId || !j.sourceAttachmentKey)throw new Error('Missing review document identity; email retained');
return {json:{uniqueKey:[j.sourceMessageId,j.sourceAttachmentKey].map(encodeURIComponent).join(':'),
 invoiceNumber:j.invoiceNumber||'',vendor:j.provider||'',invoiceDate:j.date||'',amount:j.amount??'',
 currency:j.currency||'EUR',category:j.type||'',fileName:j.originalFileName||j.fileName||'',
 targetPath:j.targetPath||'',status:'review',sourceMessageId:j.sourceMessageId,
 sourceAttachmentKey:j.sourceAttachmentKey,processedAt:new Date().toISOString(),reason:j.reason||'Invoice requires review'}};

const src=$('Prepare review row').item.json;
if(String($json.uniqueKey||'')!==src.uniqueKey)throw new Error('Review Queue write confirmation mismatch');
return {json:{status:'review',sourceMessageId:src.sourceMessageId,sourceAttachmentKey:src.sourceAttachmentKey,
 invoiceNumber:src.invoiceNumber,fileName:src.fileName}};

const outcomes=$input.all();
const expected=$('Normalize PDF binary').all();
const groups=new Map();
for(let i=0;i<outcomes.length;i++) {
 const j=outcomes[i].json;
 if(!j.sourceMessageId || !j.sourceAttachmentKey || !['archived','duplicate','review'].includes(j.status))
   throw new Error('Unexpected attachment completion; email retained');
 if(!groups.has(j.sourceMessageId))groups.set(j.sourceMessageId,{keys:new Map(),invoices:[],files:[],index:i});
 const g=groups.get(j.sourceMessageId);
 if(g.keys.has(j.sourceAttachmentKey))throw new Error('Duplicate attachment completion; email retained');
 g.keys.set(j.sourceAttachmentKey,j.status);g.invoices.push(j.invoiceNumber);g.files.push(j.fileName);
}
const completed=[];
for(const [id,g] of groups) {
 const keys=expected.filter(i=>String(i.json.id||i.json.messageId||'')===id).map(i=>i.json.attachmentKey);
 if(!keys.length || keys.length!==g.keys.size || keys.some(k=>!g.keys.has(k)))
   throw new Error('Not all invoice PDFs have completed; email retained');
 if([...g.keys.values()].includes('review'))continue;
 completed.push({json:{sourceMessageId:id,invoiceNumbers:g.invoices,files:g.files,
   archivedAttachments:g.keys.size,duplicateAttachments:[...g.keys.values()].filter(s=>s==='duplicate').length},
   pairedItem:{item:g.index}});
}
return completed;
